/****** Object:  StoredProcedure [dbo].[sp_create_production_batch]    Script Date: 18.05.2026 9:51:05 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [dbo].[sp_create_production_batch]
    @order_id BIGINT,
    @batch_number NVARCHAR(50),
    @extruder_program NVARCHAR(MAX) = NULL,
    @user_id BIGINT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    
    DECLARE @product_id BIGINT, @recipe_version_id BIGINT, @tech_card_id BIGINT;
    DECLARE @new_batch_id BIGINT;
    
    BEGIN TRY
        BEGIN TRANSACTION;
        
        -- Валидация
        IF @order_id IS NULL OR @batch_number IS NULL
        BEGIN
            RAISERROR('order_id и batch_number обязательны для заполнения', 16, 1);
            ROLLBACK;
            RETURN;
        END;
        
        -- Проверяем существование заказа
        IF NOT EXISTS (SELECT 1 FROM production_orders WHERE id = @order_id)
        BEGIN
            RAISERROR('Заказ с id %d не найден', 16, 1, @order_id);
            ROLLBACK;
            RETURN;
        END;
        
        -- Получаем данные из заказа (в production_orders нет product_id, берем из recipes)
        SELECT TOP 1 
            @recipe_version_id = po.recipe_id,
            @product_id = r.product_id
        FROM production_orders po
        INNER JOIN recipes r ON po.recipe_id = r.id
        WHERE po.id = @order_id;
        
        -- Получаем активную техкарту
        SELECT TOP 1 @tech_card_id = id
        FROM tech_cards
        WHERE product_id = @product_id AND is_active = 1;
        
        -- Если техкарты нет, создаём дефолтную
        IF @tech_card_id IS NULL
        BEGIN
            INSERT INTO tech_cards (product_id, version, status, is_active)
            VALUES (@product_id, '1.0', 'active', 1);
            SET @tech_card_id = SCOPE_IDENTITY();
        END;
        
        -- Создаём партию
        INSERT INTO production_batches (
            batch_number, order_id, product_id, 
            recipe_version_id, tech_card_id, status, 
            created_at
        )
        VALUES (
            @batch_number, @order_id, @product_id,
            @recipe_version_id, @tech_card_id, 'planned',
            GETDATE()
        );
        
        SET @new_batch_id = SCOPE_IDENTITY();
        
        -- Создаём записи шагов из техкарты
        INSERT INTO batch_step_actual (batch_id, step_order, step_name, status)
        SELECT 
            @new_batch_id, 
            step_order, 
            name,
            'pending'
        FROM tech_steps
        WHERE tech_card_id = @tech_card_id
        ORDER BY step_order;
        
        -- Логируем аудит
        INSERT INTO audit_events (event_type, object_type, object_id, description, created_by)
        VALUES ('CREATE', 'production_batch', @new_batch_id, 
                'Создана партия ' + @batch_number, ISNULL(@user_id, 0));
        
        COMMIT TRANSACTION;
        
        SELECT @new_batch_id AS batch_id, 'Партия успешно создана' AS message;
    END TRY
    BEGIN CATCH
        ROLLBACK;
        THROW;
    END CATCH
END;
GO
